div.script:
(function () {
    var g = document.currentScript && document.currentScript.parentNode;
    if (!g || g.getAttribute('data-vista')) { return; }
    try {
        if (window.localStorage.getItem('shrimp_misprod_vista') === 'lista') { g.classList.add('s-products--list'); }
    } catch (e) {}
})();

template.script:
(function () {
    var pend = null;
    document.addEventListener('click', function (e) {
        var b = e.target.closest('.prod-del-btn');
        if (!b) { return; }
        pend = b.closest('form');
        var modo = b.getAttribute('data-modo') || 'eliminar';
        var nombre = b.getAttribute('data-nombre') || '';
        var t = document.getElementById('prodConfirmTitle');
        var x = document.getElementById('prodConfirmTxt');
        var ok = document.getElementById('prodConfirmOk');
        if (modo === 'archivar') {
            t.textContent = 'Archivar producto';
            x.innerHTML = 'Este producto ya tiene ventas, así que no se elimina: se archivará y saldrá del marketplace. Podrás reactivarlo después. «»';
            ok.textContent = 'Archivar';
            ok.classList.remove('s-btn-danger'); ok.classList.add('s-btn-primary');
        } else {
            t.textContent = 'Eliminar producto';
            x.innerHTML = '¿Seguro que quieres eliminar «»? Saldrá de tu lista y pasará al histórico; no volverás a verlo ni podrás reactivarlo.';
            ok.textContent = 'Eliminar';
            ok.classList.remove('s-btn-primary'); ok.classList.add('s-btn-danger');
        }
        var s = x.querySelector('strong'); if (s) { s.textContent = nombre; }
        document.getElementById('prodConfirmModal').classList.add('open');
    });
    window.prodCloseConfirm = function () {
        document.getElementById('prodConfirmModal').classList.remove('open');
        pend = null;
    };
    window.prodDoConfirm = function () { if (pend) { pend.submit(); } };
    document.getElementById('prodConfirmModal').addEventListener('click', function (e) {
        if (e.target === this) { window.prodCloseConfirm(); }
    });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') { window.prodCloseConfirm(); }
    });
})();

(function () {
function init() {
var page = document.getElementById("pd_page");
if (!page) { return; }

// Galería: miniaturas, flechas y teclado.
var mainImg = document.getElementById("mp_main_img");
var thumbsWrap = document.getElementById("mp_thumbs");
var counter = document.getElementById("pd_gal_i");
if (mainImg && thumbsWrap) {
var thumbs = Array.prototype.slice.call(thumbsWrap.querySelectorAll(".mp-thumb"));
var setActive = function (idx) {
var t = thumbs[idx];
if (!t) { return; }
mainImg.src = t.dataset.url;
mainImg.dataset.index = String(idx);
thumbs.forEach(function (el, i) { el.classList.toggle("is-active", i === idx); });
if (counter) { counter.textContent = String(idx + 1); }
};
var go = function (d) {
var n = thumbs.length;
var cur = parseInt(mainImg.dataset.index || "0", 10);
setActive((cur + d + n) % n);
};
thumbsWrap.addEventListener("click", function (e) {
var t = e.target.closest(".mp-thumb");
if (t) { setActive(parseInt(t.dataset.index || "0", 10)); }
});
thumbsWrap.addEventListener("keydown", function (e) {
var t = e.target.closest(".mp-thumb");
if (t && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); setActive(parseInt(t.dataset.index || "0", 10)); }
});
var prev = document.getElementById("mp_prev_btn");
var next = document.getElementById("mp_next_btn");
if (prev) { prev.addEventListener("click", function () { go(-1); }); }
if (next) { next.addEventListener("click", function () { go(1); }); }
setActive(0);
}

// Columna derecha fija DEBAJO de la cabecera del sitio.
var stickyTop = function () {
var h = document.querySelector("header#top");
var top = 0;
if (h) {
var pos = window.getComputedStyle(h).position;
if (pos === "fixed" || pos === "sticky") { top = Math.max(0, Math.round(h.getBoundingClientRect().bottom)); }
}
page.style.setProperty("--pd-top", top + "px");
};
var raf = null;
window.addEventListener("scroll", function () {
if (raf) { return; }
raf = requestAnimationFrame(function () { raf = null; stickyTop(); });
}, {passive: true});
window.addEventListener("resize", stickyTop);
stickyTop();

// Visor de certificado por encima del modal de la lista.
var cv = document.getElementById("certModal");
if (cv) { document.body.appendChild(cv); }
}
if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();
